-- 0110: Our own barcode / QR for every product (Round 26).
--   Goods arrive with the supplier's barcode (or none). Every product also gets ONE code of our own, generated by the system, that never changes.
--   It is a valid EAN-13 starting with 20 (the range reserved for in-store use, so it can never clash with a supplier's or a marketplace barcode).
--   The label printed from it carries the barcode and a QR of the same number; scanning either finds the product. The supplier's barcodes stay
--   linked to the product, so both the supplier's label and ours scan to the same product.

create sequence if not exists internal_code_seq;
alter table products add column if not exists internal_code text;

create or replace function ean13_check(p12 text) returns text language sql immutable as $$
  select ((10 - (sum(substr(p12, i, 1)::int * case when i % 2 = 1 then 1 else 3 end) % 10)) % 10)::text from generate_series(1, 12) i
$$;
create or replace function gen_internal_code() returns text language plpgsql set search_path = public, pg_temp as $$
declare b text;
begin
  b := '20' || lpad(nextval('internal_code_seq')::text, 10, '0');
  return b || ean13_check(b);
end $$;

do $$
declare r record;
begin
  for r in select product_id from products where internal_code is null order by created_at, sku loop
    update products set internal_code = gen_internal_code() where product_id = r.product_id;
  end loop;
end $$;
create unique index if not exists products_internal_code_uq on products (internal_code);

create or replace function trg_internal_code() returns trigger language plpgsql set search_path = public, pg_temp as $$
begin
  if tg_op = 'INSERT' then
    if new.internal_code is null then new.internal_code := gen_internal_code(); end if;
  elsif new.internal_code is distinct from old.internal_code then
    raise exception 'A product''s own barcode never changes once it exists (labels may already be on the shelf)';
  end if;
  return new;
end $$;
drop trigger if exists trg_internal_code on products;
create trigger trg_internal_code before insert or update of internal_code on products for each row execute function trg_internal_code();

-- no other code may equal a product's own code
create or replace function trg_code_clash() returns trigger language plpgsql set search_path = public, pg_temp as $$
begin
  if tg_table_name = 'product_barcodes' then
    if exists (select 1 from products p where lower(btrim(p.barcode)) = lower(btrim(new.code)) and p.product_id <> new.product_id) then
      raise exception 'The code % already belongs to another product', new.code;
    end if;
    if exists (select 1 from products p where p.internal_code = btrim(new.code)) then
      raise exception 'The code % is one of our own generated barcodes', new.code;
    end if;
  else
    if new.barcode is not null and exists (select 1 from product_barcodes b where lower(btrim(b.code)) = lower(btrim(new.barcode)) and b.product_id <> new.product_id) then
      raise exception 'The code % is already linked to another product', new.barcode;
    end if;
    if new.barcode is not null and exists (select 1 from products p where p.internal_code = btrim(new.barcode) and p.product_id <> new.product_id) then
      raise exception 'The code % is one of our own generated barcodes', new.barcode;
    end if;
  end if;
  return new;
end $$;

create or replace function scan_catalog()
returns table (code text, product_id uuid, sku text, product_name text, size text, colour text, lot_tracked boolean, status text, pack_qty int, kind text)
language sql stable set search_path = public, pg_temp as $$
  select lower(btrim(p.internal_code)), p.product_id, p.sku, p.name, p.size, p.colour, p.lot_tracked, p.status, 1, 'own' from products p where p.internal_code is not null
  union all
  select lower(btrim(p.barcode)), p.product_id, p.sku, p.name, p.size, p.colour, p.lot_tracked, p.status, 1, 'barcode' from products p where p.barcode is not null
  union all
  select lower(btrim(p.sku)), p.product_id, p.sku, p.name, p.size, p.colour, p.lot_tracked, p.status, 1, 'sku' from products p
  union all
  select lower(btrim(b.code)), p.product_id, p.sku, p.name, p.size, p.colour, p.lot_tracked, p.status, b.pack_qty, b.kind
    from product_barcodes b join products p on p.product_id = b.product_id
  order by 1, 2, 10
$$;
revoke execute on function scan_catalog() from public, anon;
grant execute on function scan_catalog() to authenticated;

-- which labels were printed, and how many
create table if not exists product_label_log (
  log_id     uuid primary key default gen_random_uuid(),
  product_id uuid not null references products(product_id),
  copies     int not null check (copies between 1 and 10000),
  printed_by uuid default auth.uid(),
  printed_at timestamptz not null default now()
);
create index if not exists pll_product on product_label_log (product_id, printed_at desc);
alter table product_label_log enable row level security;
drop policy if exists "label log read" on product_label_log; create policy "label log read" on product_label_log for select to authenticated using (true);
grant select on product_label_log to authenticated;

create or replace function labels_log(p_items jsonb) returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare e jsonb; n int := 0;
begin
  if not (has_grn_write() or current_role_name() in ('Super Admin', 'Operations Manager')) then raise exception 'Only Operations or Warehouse roles can print labels'; end if;
  for e in select * from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) loop
    insert into product_label_log (product_id, copies) values ((e ->> 'product_id')::uuid, greatest(1, least(10000, coalesce(nullif(e ->> 'copies', '')::int, 1))));
    n := n + 1;
  end loop;
  return n;
end $$;

-- take away a wrongly linked supplier / carton code (our own generated code and the product's main barcode cannot be removed here)
create or replace function product_code_unlink(p_code_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not (has_grn_write() or current_role_name() in ('Super Admin', 'Operations Manager')) then raise exception 'Only Operations or Warehouse roles can change linked codes'; end if;
  delete from product_barcodes where code_id = p_code_id;
  if not found then raise exception 'That code is not linked any more'; end if;
end $$;

revoke execute on function labels_log(jsonb), product_code_unlink(uuid) from public, anon;
grant execute on function labels_log(jsonb), product_code_unlink(uuid) to authenticated;
